  public Action OnClosed;
  public bool IsOpen=>screen!=null&&screen.gameObject.activeSelf;public bool GiftVisible=>gift!=null&&gift.activeSelf;
  static readonly Color Ink=new Color32(64,33,23,255);
  static RectTransform Rect(Transform p,string n,Vector2 a,Vector2 b){var r=new GameObject(n,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(p,false);r.anchorMin=a;r.anchorMax=b;r.offsetMin=r.offsetMax=Vector2.zero;return r;}
  Image Image(Transform p,string n,Sprite s,Vector2 a,Vector2 b,bool sliced=false){var im=Rect(p,n,a,b).gameObject.AddComponent<Image>();im.sprite=s;im.raycastTarget=false;im.type=sliced?UnityEngine.UI.Image.Type.Sliced:UnityEngine.UI.Image.Type.Simple;if(sliced)im.pixelsPerUnitMultiplier=2;return im;}
  Text Text(Transform p,string n,string value,int size,Color color,Vector2 a,Vector2 b){var t=Rect(p,n,a,b).gameObject.AddComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=value;t.color=color;t.fontSize=size;t.resizeTextForBestFit=true;t.resizeTextMinSize=15;t.resizeTextMaxSize=size;t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;return t;}
  Button Button(Transform p,string n,string value,Vector2 a,Vector2 b,Action click){var im=Image(p,n,art.button,a,b,false);im.raycastTarget=true;var button=im.gameObject.AddComponent<Button>();button.targetGraphic=im;buttons.Add(button);button.onClick.AddListener(()=>click());var text=Text(im.transform,"Label",value,25,Color.white,new Vector2(.05f,.14f),new Vector2(.95f,.86f));var shadow=text.gameObject.AddComponent<Shadow>();shadow.effectColor=new Color(0,0,.2f,.8f);shadow.effectDistance=new Vector2(1,-2);return button;}
  public void Mount(RectTransform safeArea)
  {
   safe=safeArea;art=Resources.Load<DailyArt>("Daily/Art");if(art==null)throw new InvalidOperationException("Daily art missing");
   var entry=Image(safe,"DailyHomeEntries",Resources.Load<Sprite>("Gameplay/HUD/HUD_Panel_v001"),new Vector2(.018f,.55f),new Vector2(.225f,.70f),true);entry.color=new Color(.85f,.8f,1,1);
   var giftIcon=Image(entry.transform,"GiftIcon",art.chest,new Vector2(.10f,.70f),new Vector2(.90f,1));giftIcon.preserveAspect=true;Button(entry.transform,"DailyGiftButton","Daily Gift",new Vector2(.04f,.57f),new Vector2(.96f,.80f),()=>Open(true));
   var missionIcon=Image(entry.transform,"MissionIcon",art.star,new Vector2(.30f,.23f),new Vector2(.70f,.53f));missionIcon.preserveAspect=true;Button(entry.transform,"MissionsButton","Missions",new Vector2(.04f,.02f),new Vector2(.96f,.25f),()=>Open(false));
   screen=Rect(safe,"DailyActivitiesScreen",Vector2.zero,Vector2.one);var block=screen.gameObject.AddComponent<UnityEngine.UI.Image>();block.color=new Color(.025f,.03f,.12f,1);block.raycastTarget=true;
   background=Image(screen,"DailySky",art.sky,Vector2.zero,Vector2.one);background.color=new Color(.65f,.65f,.86f,1);var castle=Image(screen,"DailyCastle",art.castle,Vector2.zero,Vector2.one);castle.preserveAspect=true;castle.color=new Color(.65f,.65f,.83f,1);
   var header=Image(screen,"DailyHeader",Resources.Load<Sprite>("Gameplay/HUD/HUD_Panel_v001"),new Vector2(.02f,.915f),new Vector2(.98f,.995f),true);Text(header.transform,"Title","GÜNLÜK BÜYÜLER",38,Color.white,new Vector2(.04f,.15f),new Vector2(.73f,.85f));Button(header.transform,"DailyClose","GERİ",new Vector2(.76f,.15f),new Vector2(.96f,.85f),Close);
   hero=Rect(screen,"DailyHero",new Vector2(.01f,.65f),new Vector2(.99f,.915f));var chest=Image(hero,"DailyRewardChest",art.chest,new Vector2(.30f,0),new Vector2(.99f,1));chest.preserveAspect=true;
   var catObject=Instantiate(art.catPrefab,hero,false);catObject.name="DailyWizardCat";cat=catObject.GetComponent<RectTransform>();cat.anchorMin=cat.anchorMax=new Vector2(.23f,.02f);cat.pivot=new Vector2(.5f,0);cat.anchoredPosition=Vector2.zero;foreach(var g in cat.GetComponentsInChildren<Graphic>())g.raycastTarget=false;
   Button(screen,"DailyTasksTab","GÖREVLER",new Vector2(.03f,.59f),new Vector2(.49f,.65f),()=>ShowTab(false));Button(screen,"DailyGiftTab","GÜNLÜK HEDİYE",new Vector2(.51f,.59f),new Vector2(.97f,.65f),()=>ShowTab(true));
   tasks=Image(screen,"DailyTasksPanel",art.parchment,new Vector2(.02f,.12f),new Vector2(.98f,.59f),true).gameObject;
   Text(tasks.transform,"DailyTasksTitle","Günlük Görevler",32,Ink,new Vector2(.04f,.86f),new Vector2(.96f,.98f));
   for(int i=0;i<4;i++){int index=i;float y=.665f-i*.18f;var row=Image(tasks.transform,"DailyTask_"+i,art.parchment,new Vector2(.025f,y),new Vector2(.975f,y+.18f),true);row.color=new Color(1,.94f,.85f,1);var icon=Image(row.transform,"MissionIcon",i==0?art.rewards[2]:i==1||i==2?art.star:art.rewards[1],new Vector2(.025f,.22f),new Vector2(.15f,.85f));icon.preserveAspect=true;
    var title=Text(row.transform,"TaskTitle",DailyRules.Title((DailyTaskKind)i),24,Ink,new Vector2(.16f,.47f),new Vector2(.67f,.92f));title.alignment=TextAnchor.MiddleLeft;
    var track=Image(row.transform,"ProgressTrack",art.button,new Vector2(.17f,.17f),new Vector2(.65f,.39f));track.color=new Color(.1f,.25f,.15f,1);fills[i]=Image(track.transform,"GreenProgress",art.button,Vector2.zero,Vector2.one);fills[i].type=UnityEngine.UI.Image.Type.Filled;fills[i].fillMethod=UnityEngine.UI.Image.FillMethod.Horizontal;fills[i].color=new Color(.15f,1,.15f,1);
