   }
   timer=Text(tasks.transform,"DailyReset","",20,Ink,new Vector2(.05f,.015f),new Vector2(.95f,.10f));
   gift=Image(screen,"DailyGiftPanel",art.parchment,new Vector2(.02f,.12f),new Vector2(.98f,.59f),true).gameObject;Text(gift.transform,"GiftTitle","Günlük Giriş Hediyesi",38,Ink,new Vector2(.07f,.77f),new Vector2(.93f,.94f));var giftReward=Image(gift.transform,"DailyGiftReward",art.rewards[1],new Vector2(.36f,.47f),new Vector2(.64f,.76f));giftReward.preserveAspect=true;Text(gift.transform,"GiftAmount","+1 İPUCU",32,Ink,new Vector2(.10f,.38f),new Vector2(.90f,.49f));giftState=Text(gift.transform,"GiftState","",25,Ink,new Vector2(.10f,.22f),new Vector2(.90f,.38f));giftClaim=Button(gift.transform,"ClaimDailyGift","HEDİYEYİ AL",new Vector2(.20f,.08f),new Vector2(.80f,.22f),ClaimGift);
   status=Text(screen,"DailyStatus","",22,Color.white,new Vector2(.05f,.02f),new Vector2(.95f,.105f));screen.gameObject.SetActive(false);
